// Baca CONFIG (key/value) -> objek cfg + gate followup_enabled + gate jam etis WIB.
const rows = $input.all().map(i => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : '';
}
const num = (k, d) => {
  const raw = cfg[k];
  if (raw === undefined || raw === '') return d;
  const n = Number(raw);
  return isNaN(n) ? d : n;
};

// Kill switch utama -- WAJIB string "true" persis, bukan truthy sembarangan.
if (String(cfg.followup_enabled || '').trim().toLowerCase() !== 'true') {
  console.log('follow-up dimatikan (followup_enabled != "true") -- run berhenti di sini.');
  return [];
}

let templates = [];
try { templates = JSON.parse(cfg.followup_templates || '[]'); } catch (e) { templates = []; }
if (!Array.isArray(templates) || !templates.length) {
  console.log('followup_templates kosong/tidak valid -- tidak ada yang bisa dikirim, run berhenti.');
  return [];
}

const openH = num('followup_open_hour', 9);
const closeH = num('followup_close_hour', 21);
const wibParts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
const wibHour = Number((wibParts.find(p => p.type === 'hour') || {}).value || 0);
const wibMin = Number((wibParts.find(p => p.type === 'minute') || {}).value || 0);

// Di luar jam etis -> stop; trigger jam berikutnya coba lagi. Kandidat yang
// "ketinggalan" otomatis terkirim di slot berikutnya (antrian tidak hilang).
if (wibHour < openH || wibHour >= closeH) {
  console.log('di luar jendela follow-up [' + openH + '-' + closeH + ') WIB -- run berhenti.');
  return [];
}

// Jeda antar kirim & plafon per run TIDAK diwajibkan sebagai CONFIG key baru di
// brief, jadi dipakai default aman di sini. Kalau Steven menambahkan
// followup_min_delay_sec / followup_max_delay_sec / followup_max_per_run ke
// CONFIG nanti, nilainya otomatis dipakai (opsional, tidak wajib diisi).
let minDelay = num('followup_min_delay_sec', 20);
let maxDelay = num('followup_max_delay_sec', 45);
if (minDelay < 3) minDelay = 3;
if (maxDelay < minDelay) maxDelay = minDelay + 5;
let maxPerRun = num('followup_max_per_run', 20);
if (maxPerRun < 1) maxPerRun = 1;
if (maxPerRun > 300) maxPerRun = 300;

const adminPhone = String(cfg.admin_phone || '').replace(/\D/g, '') || '6285171701168';

return [{ json: {
  config: {
    // Token Fonnte (menggantikan kirimi user_code/secret/device_id).
    fonnte_token: String(cfg.fonnte_token || '').trim(),
    admin_phone: adminPhone,
    admin_phone_display: String(cfg.admin_phone_display || '').trim(),
    bot_wa_number: String(cfg.bot_wa_number || '').replace(/\D/g, ''),
    followup_max: num('followup_max', 2),
    followup_interval_hours: num('followup_interval_hours', 24),
    templates: templates,
    min_delay: minDelay,
    max_delay: maxDelay,
    max_per_run: maxPerRun,
    open_hour: openH,
    close_hour: closeH
  },
  now_epoch: Math.floor(Date.now() / 1000)
} }];

// Saring baris STATS -> user layak follow-up sekarang, lalu batasi jumlah per run
// supaya tidak memberondong (throttle waktu + plafon config).
const base = $('Parse Config FU').first().json;
const cfg = base.config;
const now = base.now_epoch;
const intervalSec = (cfg.followup_interval_hours || 24) * 3600;

const wibParts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
const wibHour = Number((wibParts.find(p => p.type === 'hour') || {}).value || 0);
const wibMin = Number((wibParts.find(p => p.type === 'minute') || {}).value || 0);

const excludeNumbers = [cfg.admin_phone, cfg.admin_phone_display, cfg.bot_wa_number]
  .map(v => String(v || '').replace(/\D/g, '')).filter(Boolean);

// Isi placeholder {key} dengan value dari STATS. Kalau value kosong, placeholder
// dihapus dan sisa kalimat dirapikan (bukan cuma string-replace polos) supaya
// tidak pernah terkirim kalimat rusak seperti "Halo kak ,".
function fillPlaceholder(text, key, value) {
  const re = new RegExp('\\{\\s*' + key + '\\s*\\}', 'gi');
  if (value) return text.replace(re, value);
  // Pola umum "kak {placeholder}" -> tinggal "kak" (honorific tanpa nama).
  text = text.replace(new RegExp('\\s*\\bkak\\s*' + re.source, 'gi'), ' kak');
  // Sisa placeholder polos (tanpa 'kak' di depan) -> hapus + rapikan spasi/koma.
  text = text.replace(re, '');
  text = text.replace(/\s+,/g, ',');
  text = text.replace(/,\s*,/g, ',');
  text = text.replace(/\s{2,}/g, ' ');
  text = text.replace(/\s+([.,!?])/g, '$1');
  return text.trim();
}

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const row = item.json;
  const noWa = String(row['No WA'] || '').trim();
  if (!noWa) continue;                                          // wajib ada No WA
  const digits = noWa.replace(/\D/g, '');
  if (!digits) continue;
  if (seen.has(digits)) continue;                                // dedupe kalau STATS ada baris ganda
  if (excludeNumbers.includes(digits)) continue;                 // nomor Steven sendiri dikecualikan

  if (/^off$/i.test(String(row['bot_mode'] || '').trim())) continue;         // HITL aktif, jangan diganggu
  if (Number(row['Counter'] || 0) < 1) continue;                 // belum pernah chat

  const lastReply = Number(row['last_reply_ts'] || 0);
  if (!lastReply) continue;                                      // belum pernah dibalas bot
  if (now - lastReply < intervalSec) continue;                   // belum lewat interval sejak balasan terakhir

  const lastFu = Number(row['last_follow_up_ts'] || 0);
  if (lastFu && now - lastFu < intervalSec) continue;             // belum lewat interval sejak follow-up terakhir

  const fuCount = Number(row['follow_up_count'] || 0);
  if (fuCount >= cfg.followup_max) continue;                      // follow_up_count harus < followup_max

  if (/^y$/i.test(String(row['deck_requested'] || '').trim())) continue;  // sudah minta deck -> Steven pegang manual

  const namaVal = String(row['Nama'] || '').trim();
  const bisnisVal = String(row['nama_bisnis'] || '').trim();
  let msg = String(cfg.templates[fuCount % cfg.templates.length] || '');
  msg = fillPlaceholder(msg, 'nama', namaVal);
  msg = fillPlaceholder(msg, 'nama_bisnis', bisnisVal);

  seen.add(digits);
  out.push({ json: {
    no_wa: noWa,
    lid: String(row['lid'] || '').trim(),
    nama: namaVal,
    follow_up_count: fuCount,
    prev_last_fu: lastFu || '',                                   // untuk rollback kalau kirim gagal
    last_reply_ts: lastReply,
    message: msg
  } });
}

// Prioritas antrian: yang belum pernah di-follow-up dulu, lalu yang paling lama tidak dibalas.
out.sort((a, b) => {
  const af = Number(a.json.follow_up_count), bf = Number(b.json.follow_up_count);
  if (af !== bf) return af - bf;
  return Number(a.json.last_reply_ts) - Number(b.json.last_reply_ts);
});

// Batas per-run = min(plafon config, kapasitas waktu tersisa sebelum jam tutup) -- supaya tidak memberondong.
const avgDelay = ((cfg.min_delay + cfg.max_delay) / 2) + 2;       // +2s estimasi latency API
const minutesToClose = Math.max(0, (cfg.close_hour - wibHour) * 60 - wibMin);
const capByTime = Math.floor((minutesToClose * 60) / avgDelay);
const cap = Math.max(0, Math.min(cfg.max_per_run, capByTime));

return out.slice(0, cap);
